/** Computes the size in bytes of encoded fields. */
public object WireSize {
    public fun varint32(value: Int): Int = when {
        value and (0.inv() shl 7) == 0 -> 1
        value and (0.inv() shl 14) == 0 -> 2
        value and (0.inv() shl 21) == 0 -> 3
        value and (0.inv() shl 28) == 0 -> 4
        else -> 5
    }

    public fun varint64(value: Long): Int {
        var v = value
        var n = 2
        if (v and (-1L shl 7) == 0L) return 1
        if (v < 0L) return 10
        if (v and (-1L shl 35) != 0L) {
            n += 4
            v = v ushr 28
        }
        if (v and (-1L shl 21) != 0L) {
            n += 2
            v = v ushr 14
        }
        if (v and (-1L shl 14) != 0L) n += 1
        return n
    }

    public fun tag(number: Int): Int = varint32(number shl 3)

    public fun int32NoTag(value: Int): Int = if (value >= 0) varint32(value) else 10

    public fun sint32NoTag(value: Int): Int = varint32((value shl 1) xor (value shr 31))

    public fun sint64NoTag(value: Long): Int = varint64((value shl 1) xor (value shr 63))

    public fun int32(number: Int, value: Int): Int = tag(number) + int32NoTag(value)

    public fun uint32(number: Int, value: Int): Int = tag(number) + varint32(value)

    public fun sint32(number: Int, value: Int): Int = tag(number) + sint32NoTag(value)

    public fun int64(number: Int, value: Long): Int = tag(number) + varint64(value)

    public fun sint64(number: Int, value: Long): Int = tag(number) + sint64NoTag(value)

    public fun fixed32(number: Int): Int = tag(number) + 4

    public fun fixed64(number: Int): Int = tag(number) + 8

    public fun bool(number: Int): Int = tag(number) + 1

    public fun string(number: Int, value: String): Int {
        val length = utf8Size(value)
        return tag(number) + varint32(length) + length
    }

    public fun bytes(number: Int, value: ByteString): Int = tag(number) + varint32(value.size) + value.size

    public fun message(number: Int, value: WireMessage): Int {
        val length = value.getSerializedSize()
        return tag(number) + varint32(length) + length
    }

    public fun packed(number: Int, payload: Int): Int = tag(number) + varint32(payload) + payload

    public fun packedEnumPayload(values: List<WireEnum>): Int {
        var n = 0
        for (v in values) n += int32NoTag(v.number)
        return n
    }

    public fun packedInt32Payload(values: List<Int>): Int {
        var n = 0
        for (v in values) n += int32NoTag(v)
        return n
    }

    public fun packedUInt32Payload(values: List<Int>): Int {
        var n = 0
        for (v in values) n += varint32(v)
        return n
    }

    public fun packedSInt32Payload(values: List<Int>): Int {
        var n = 0
        for (v in values) n += sint32NoTag(v)
        return n
    }

    public fun packedInt64Payload(values: List<Long>): Int {
        var n = 0
        for (v in values) n += varint64(v)
        return n
    }

    public fun packedSInt64Payload(values: List<Long>): Int {
        var n = 0
        for (v in values) n += sint64NoTag(v)
        return n
    }

    private fun utf8Size(value: String): Int {
        var n = 0
        var i = 0
        while (i < value.length) {
            val c = value[i]
            when {
                c.code < 0x80 -> n += 1
                c.code < 0x800 -> n += 2
                c.isHighSurrogate() && i + 1 < value.length && value[i + 1].isLowSurrogate() -> {
                    n += 4
                    i++
                }
                c.isSurrogate() -> return value.encodeToByteArray().size
                else -> n += 3
            }
            i++
        }
        return n
    }
}
